<?php
/**
 * The wording of the dues-invoice email.
 *
 * Staff can replace three pieces of it in Settings → Dues & Billing — the
 * SUBJECT, the INTRO (greeting + the "your invoice totals $X" sentence) and
 * the CLOSING (the sign-off) — using merge tags such as {firm}, {year} and
 * {total}. Everything else is generated by the system and cannot be edited
 * away: the list of who the invoice covers and what each is charged, the
 * payment link, and the mail-a-check address. A blank field means "use the
 * built-in wording", which is exactly what the email said before this
 * existed.
 *
 * This class is PURE (no WordPress): build() assembles the message from plain
 * values, so the wording rules — and that the built-in text is byte-for-byte
 * unchanged — are unit-tested (tests/InvoiceEmailTest.php).
 * MyNJILGA_Invoice_Sender::compose() gathers the values and calls it.
 */
class MyNJILGA_Invoice_Email {

    /** Settings key for each editable piece. */
    const FIELDS = [
        'subject' => 'email_subject',
        'intro'   => 'email_intro',
        'closing' => 'email_closing',
    ];

    /** Merge tag => what it becomes. */
    const TAGS = [
        'firm'       => 'The firm\'s name (or "your firm" if there isn\'t one)',
        'year'       => 'The dues year, e.g. 2027',
        'total'      => 'The invoice total, e.g. $325.00',
        'name'       => 'The bill-to contact\'s full name',
        'first_name' => 'The bill-to contact\'s first name',
        'invoice'    => 'What the invoice is: "membership dues invoice", or the assessment\'s name followed by "invoice"',
    ];

    const MAX_SUBJECT = 200;
    const MAX_TEXT    = 2000;

    /** The pay-link line. Always present: custom wording cannot remove it. */
    const PAY_LINE = 'Pay online here: ';

    /** Shown in a preview of an invoice that has not been created yet. */
    const PLACEHOLDER_LINK = '[the payment link appears here once the invoice is created]';

    // -------------------------------------------------------------------------
    // The built-in wording, as templates (shown as the field placeholders)
    // -------------------------------------------------------------------------

    public static function default_template( string $field ): string {
        switch ( $field ) {
            case 'subject':
                return '{year} NJILGA Membership Dues Invoice — {firm}';
            case 'intro':
                return "Hi {name},\n\n{firm}'s {year} NJILGA {invoice} totals {total}.";
            case 'closing':
                return "Thank you,\nNJILGA";
        }
        return '';
    }

    // -------------------------------------------------------------------------
    // Cleaning what staff type
    // -------------------------------------------------------------------------

    /**
     * Normalise a piece of wording for storage: plain text only, bounded,
     * no control characters; a subject is one line.
     */
    public static function clean( string $field, string $raw ): string {
        $s = str_replace( [ "\r\n", "\r" ], "\n", $raw );
        $s = strip_tags( $s );
        $s = (string) preg_replace( '/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/', '', $s );
        if ( $field === 'subject' ) {
            $s = trim( (string) preg_replace( '/\s+/', ' ', $s ) );
            return self::cut( $s, self::MAX_SUBJECT );
        }
        $s = trim( (string) preg_replace( "/\n{3,}/", "\n\n", $s ) );
        return self::cut( $s, self::MAX_TEXT );
    }

    private static function cut( string $s, int $max ): string {
        return function_exists( 'mb_substr' ) ? mb_substr( $s, 0, $max ) : substr( $s, 0, $max );
    }

    /**
     * Merge tags in $text that aren't ones we know — a typo like {frim} would
     * otherwise be emailed to a firm as literal text.
     *
     * @return array<int,string> The unknown tag names (lower-cased, de-duplicated).
     */
    public static function unknown_tags( string $text ): array {
        if ( ! preg_match_all( '/\{([A-Za-z0-9_]+)\}/', $text, $m ) ) {
            return [];
        }
        $unknown = [];
        foreach ( $m[1] as $tag ) {
            $tag = strtolower( $tag );
            if ( ! isset( self::TAGS[ $tag ] ) ) {
                $unknown[ $tag ] = $tag;
            }
        }
        return array_values( $unknown );
    }

    // -------------------------------------------------------------------------
    // Rendering
    // -------------------------------------------------------------------------

    /**
     * Replace {tags} with their values. A tag that isn't known is left exactly
     * as written.
     *
     * @param array<string,string> $vars tag => value
     */
    public static function render( string $template, array $vars ): string {
        return (string) preg_replace_callback(
            '/\{([A-Za-z0-9_]+)\}/',
            static function ( array $m ) use ( $vars ) {
                $tag = strtolower( $m[1] );
                return array_key_exists( $tag, $vars ) ? (string) $vars[ $tag ] : $m[0];
            },
            $template
        );
    }

    /**
     * The values behind the merge tags.
     *
     * @param array<string,mixed> $in build()'s input.
     * @return array<string,string>
     */
    public static function vars( array $in ): array {
        $firm  = trim( (string) ( $in['firm'] ?? '' ) );
        $label = trim( (string) ( $in['assessment_label'] ?? '' ) );
        $name  = trim( (string) ( $in['name'] ?? '' ) );
        // A contact with only a full name on file still gets a greeting: the first word of it.
        $first = trim( (string) ( $in['first_name'] ?? '' ) );
        if ( $first === '' && $name !== '' ) {
            $first = (string) preg_split( '/\s+/', $name )[0];
        }
        return [
            'firm'       => $firm !== '' ? $firm : 'your firm',
            'year'       => (string) (int) ( $in['year'] ?? 0 ),
            'total'      => (string) ( $in['total'] ?? '' ),
            'name'       => $name,
            'first_name' => $first,
            'invoice'    => ! empty( $in['is_assessment'] )
                ? ( $label !== '' ? $label : 'assessment' ) . ' invoice'
                : 'membership dues invoice',
        ];
    }

    /**
     * Assemble the email.
     *
     * Input:
     *   is_assessment   bool    an assessment-only invoice (split-assessment billing)
     *   year            int
     *   firm            string  firm name ('' = none)
     *   total           string  already formatted, e.g. "$325.00"
     *   name            string  bill-to full name
     *   first_name      string
     *   assessment_label string the assessment's name (assessment invoices)
     *   covers          string  "This invoice covers…" block ('' = none)
     *   link            string  the payment link
     *   remittance      string  the mail-a-check address ('' = none)
     *   subject_tpl / intro_tpl / closing_tpl  string  the custom wording ('' = built-in)
     *
     * @param array<string,mixed> $in
     * @return array{subject:string,body:string}
     */
    public static function build( array $in ): array {
        $isAssess = ! empty( $in['is_assessment'] );
        $year     = (int) ( $in['year'] ?? 0 );
        $firm     = (string) ( $in['firm'] ?? '' );
        $total    = (string) ( $in['total'] ?? '' );
        $name     = (string) ( $in['name'] ?? '' );
        $label    = (string) ( $in['assessment_label'] ?? '' );
        $vars     = self::vars( $in );

        $introTpl   = trim( (string) ( $in['intro_tpl'] ?? '' ) );
        $closingTpl = trim( (string) ( $in['closing_tpl'] ?? '' ) );
        $subjectTpl = trim( (string) ( $in['subject_tpl'] ?? '' ) );

        $blocks = [];
        if ( $introTpl !== '' ) {
            $blocks[] = trim( self::render( $introTpl, $vars ) );
        } else {
            $blocks[] = sprintf( 'Hi %s,', $name );
            if ( $isAssess ) {
                $blocks[] = sprintf( 'Your %d NJILGA %s invoice totals %s.', $year, $label !== '' ? $label : 'assessment', $total );
            } else {
                $blocks[] = sprintf( '%s %d NJILGA membership dues invoice totals %s.', $firm !== '' ? $firm . "'s" : 'Your', $year, $total );
            }
        }
        $covers = (string) ( $in['covers'] ?? '' );
        if ( $covers !== '' ) {
            $blocks[] = $covers;
        }
        $blocks[] = self::PAY_LINE . (string) ( $in['link'] ?? '' );
        $remittance = trim( (string) ( $in['remittance'] ?? '' ) );
        if ( $remittance !== '' ) {
            $blocks[] = 'Pay online at the link above, or mail a check to: ' . $remittance;
        }
        $blocks[] = $closingTpl !== '' ? trim( self::render( $closingTpl, $vars ) ) : "Thank you,\nNJILGA";

        $subject = '';
        if ( $subjectTpl !== '' ) {
            // One line, whatever a merge value (a firm name) contains: a newline in a subject is a header-injection vector.
            $subject = trim( (string) preg_replace( '/\s+/', ' ', self::render( $subjectTpl, $vars ) ) );
        }
        if ( $subject === '' ) {
            $subject = $isAssess
                ? sprintf( '%d NJILGA %s Invoice', $year, $label !== '' ? $label : 'Assessment' )
                : sprintf( '%d NJILGA Membership Dues Invoice%s', $year, $firm !== '' ? ' — ' . $firm : '' );
        }

        return [ 'subject' => $subject, 'body' => implode( "\n\n", $blocks ) ];
    }

    // -------------------------------------------------------------------------
    // The example firm used by "Send test" and the wording preview
    // -------------------------------------------------------------------------

    /** What the firm picker calls the built-in example firm. */
    const SAMPLE_FIRM = 'sample';

    /**
     * An invoice row for a made-up firm, shaped exactly like a real one, so
     * a test email and the wording preview go through the SAME
     * MyNJILGA_Invoice_Sender::compose() a real send does — what you test is
     * what firms get. It has no payment link (compose() shows a flagged
     * placeholder for a preview) and a bill-to email that can never be a
     * real address.
     */
    public static function sample_row( int $year ): object {
        $members = [
            [ 'contact_id' => 0, 'name' => 'Ann Able', 'email' => 'ann.able@examplefirm.test', 'category' => 'professional', 'category_label' => 'Professional Membership', 'tier_label' => '1st Member', 'dues_cents' => 12500, 'assessment_cents' => 0 ],
            [ 'contact_id' => 0, 'name' => 'Bob Baker', 'email' => 'bob.baker@examplefirm.test', 'category' => 'professional', 'category_label' => 'Professional Membership', 'tier_label' => 'Members 2–5', 'dues_cents' => 7500, 'assessment_cents' => 0 ],
        ];
        $person  = [ 'contact_id' => 0, 'name' => 'Owen Owner', 'first_name' => 'Owen', 'last_name' => 'Owner', 'email' => 'owen.owner@examplefirm.test' ];
        $snap    = [
            'version' => 2, 'dues_year' => $year, 'billing_mode' => 'firm', 'invoice_kind' => 'combined',
            'company' => [ 'id' => 0, 'name' => 'Example Firm LLP' ],
            'owner' => $person, 'bill_to' => $person, 'members' => $members,
        ];
        return (object) [
            'id' => 0, 'fluentcrm_company_id' => 0, 'fluentcrm_owner_contact_id' => 0, 'bill_to_contact_id' => 0,
            'dues_year' => $year, 'invoice_kind' => 'combined', 'status' => 'draft',
            'total_amount_cents' => 20000, 'hosted_invoice_url' => '', 'roster_snapshot' => json_encode( $snap ),
        ];
    }

    /** Whether any of the three pieces has been customised. @param array<string,string> $tpl field => text */
    public static function is_custom( array $tpl ): bool {
        foreach ( array_keys( self::FIELDS ) as $field ) {
            if ( trim( (string) ( $tpl[ $field ] ?? '' ) ) !== '' ) {
                return true;
            }
        }
        return false;
    }

    /**
     * The custom wording as saved in Settings → Dues & Billing.
     *
     * @return array{subject:string,intro:string,closing:string}
     */
    public static function settings(): array {
        $out = [ 'subject' => '', 'intro' => '', 'closing' => '' ];
        foreach ( self::FIELDS as $field => $key ) {
            $out[ $field ] = trim( (string) MyNJILGA_Dues_Settings::general( $key, '' ) );
        }
        return $out;
    }
}
